#include <array>
#include <cstddef>
#include <iostream>
#include <string>

template <typename T, std::size_t N>
class RingBuffer
{
public:
    void push(const T& value)
    {
        m_items[(m_head + m_count) % N] = value;
        if (m_count < N) ++m_count;
        else m_head = (m_head + 1) % N;          // full: the oldest is overwritten
    }

    std::size_t size() const { return m_count; }
    const T& at(std::size_t i) const { return m_items[(m_head + i) % N]; }
    // TODO: full, oldest, newest

private:
    std::array<T, N> m_items{};
    std::size_t m_head{ 0 };
    std::size_t m_count{ 0 };
};

int main()
{
    RingBuffer<std::string, 5> history{};
    for (const char* command : { "look", "go north", "take key", "go east", "open door", "inventory" })
        history.push(command);
    for (std::size_t i{ 0 }; i < history.size(); ++i) std::cout << i << ": " << history.at(i) << '\n';
    // TODO: a moving average of the last 10 numbers typed
    return 0;
}
